algorithm AverageOfFour
    define mutable n1 as integer <- 0;
    define mutable n2 as integer <- 0;
    define mutable n3 as integer <- 0;
    define mutable n4 as integer <- 0;
    read n1, n2, n3, n4;
    define average as real <- (n1 + n2 + n3 + n4) / 4;
    write average;
endAlgorithm
